let language=localStorage.getItem('tankrush-language')||(['en','fr','nl','de'].includes(navigator.language.slice(0,2))?navigator.language.slice(0,2):'en');
export const t=(key)=>messages[language][key]||messages.en[key]||key;
export const localizedHabitat=h=>{const v=habitatText[language]?.[h.id];return v?{region:v[0],shapeLabel:v[1],description:v[2]}:h;};
export function getLanguage(){return language;}
export function setLanguage(next){language=messages[next]?next:'en';localStorage.setItem('tankrush-language',language);document.documentElement.lang=language;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll('[data-i18n-html]').forEach(e=>e.innerHTML=t(e.dataset.i18nHtml));}
